import { JxInputField, JxButton, JxToastViewport, useJxToastQueue } from '@jinx-ui/react';

export default function NewsletterSubscribeForm() {
  const toasts = useJxToastQueue();
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);

  const isValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());
  const errorText = touched && !isValid ? 'Укажите адрес в формате name@example.com' : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setTouched(true);
    if (!isValid) return;

    toasts.push({
      title: 'Готово',
      message: `Письмо с подтверждением отправлено на ${email.trim()}`,
      variant: 'success',
      duration: 5000,
    });
    setEmail('');
    setTouched(false);
  };

  return (
    <form
      onSubmit={submit}
      noValidate
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 16,
        maxWidth: 420,
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
        <span style={{ fontFamily: 'var(--jx-font-display)', fontSize: 20, color: 'var(--jx-text)' }}>
          Подписка на рассылку
        </span>
        <span style={{ fontSize: 14, color: 'var(--jx-text-2)' }}>
          Раз в неделю — только важные обновления.
        </span>
      </div>

      <JxInputField
        label="Электронная почта"
        type="email"
        name="email"
        required
        placeholder="name@example.com"
        autoComplete="email"
        value={email}
        onChange={(event) => setEmail(event.target.value)}
        onBlur={() => setTouched(true)}
        errorText={errorText}
        helperText={errorText ? undefined : 'Отписаться можно в один клик'}
      />

      <div style={{ display: 'flex', gap: 8 }}>
        <JxButton type="submit" variant="primary">
          Подписаться
        </JxButton>
      </div>

      <JxToastViewport items={toasts.items} onDismiss={toasts.dismiss} position="bottom-right" />
    </form>
  );
}

